// A replica of the Borlabs Cookie dialog for Echo's tests, written fresh
// from Borlabs's public knowledge base: the JavaScript API
// (https://borlabs.io/kb/javascript-api/ and
// https://borlabs.io/kb/javascript-api-v3/: window.BorlabsCookie with
// Consents.hasConsent and hasConsentForServiceGroup, here also getAll)
// and what the borlabs-cookie cookie stores
// (https://borlabs.io/kb/what-information-does-borlabs-cookie-store/:
// consents by group, a UID and a version). The markup follows the
// dialog Borlabs Cookie 2 and 3 print on public pages. It is not
// Borlabs's code (Borlabs Cookie is a commercial plugin). Captured
// 2026-10-26.
//
// The page holds the dialog in <template id="replica-banner">; the
// script tag's data-show says when it appears: now, late (after 4 s) or
// never.
(function () {
  "use strict";
  var me = document.currentScript;
  var show = (me && me.getAttribute("data-show")) || "now";
  var services = { statistics: ["google-analytics"], marketing: ["facebook-pixel"], "external-media": ["youtube"] };
  var consents = null;
  var mounted = false;

  function box() { return document.getElementById("BorlabsCookieBox"); }

  function store(groups) {
    consents = { essential: ["borlabs-cookie"] };
    Object.keys(services).forEach(function (g) { consents[g] = groups[g] ? services[g].slice() : []; });
    var v = JSON.stringify({ consents: consents, domainPath: location.host + "/", expires: "", uid: "replica-" + Date.now(), version: "1" });
    document.cookie = "borlabs-cookie=" + encodeURIComponent(v) + "; path=/; max-age=31536000; SameSite=Lax";
    var b = box();
    if (b) b.classList.remove("show-cookie-box");
  }

  function all(v) {
    var g = {};
    Object.keys(services).forEach(function (k) { g[k] = v; });
    return g;
  }

  window.BorlabsCookie = {
    Consents: {
      getAll: function () { return consents; },
      hasConsent: function (service) {
        if (!consents) return false;
        return Object.keys(consents).some(function (g) { return consents[g].indexOf(service) >= 0; });
      },
      hasConsentForServiceGroup: function (group) { return !!(consents && consents[group] && consents[group].length); }
    }
  };

  function on(sel, fn) {
    var els = document.querySelectorAll(sel);
    for (var i = 0; i < els.length; i++) {
      els[i].addEventListener("click", function (e) { e.preventDefault(); fn(); });
    }
  }

  function mount() {
    if (mounted) return;
    mounted = true;
    if (!box()) {
      var tpl = document.getElementById("replica-banner");
      if (!tpl) return;
      document.body.appendChild(tpl.content.cloneNode(true));
    }
    var b = box();
    b.classList.add("show-cookie-box");
    on("[data-cookie-accept-all], [data-borlabs-cookie-actions=accept-all]", function () { store(all(true)); });
    on("[data-cookie-refuse], [data-borlabs-cookie-actions=reject]", function () { store(all(false)); });
    on("[data-cookie-individual], [data-borlabs-cookie-actions=preferences]", function () { b.classList.add("replica-open"); });
    on("[data-cookie-accept], [data-borlabs-cookie-actions=save-consents]", function () {
      var g = {};
      var boxes = b.querySelectorAll("input[data-borlabs-cookie-checkbox]");
      for (var i = 0; i < boxes.length; i++) g[boxes[i].value] = boxes[i].checked;
      store(g);
    });
  }

  if (show === "now") {
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", mount);
    else mount();
  } else if (show === "late") {
    setTimeout(mount, 4000);
  }
})();
